CREATE DATABASE IF NOT EXISTS fahizhub CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE fahizhub;

CREATE TABLE users (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin') NOT NULL DEFAULT 'admin',is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE profile (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL UNIQUE,headline VARCHAR(255),hero_title VARCHAR(255),hero_subtitle TEXT,short_bio TEXT,long_bio TEXT,current_focus TEXT,profile_image_url VARCHAR(500),timezone VARCHAR(80) NOT NULL DEFAULT 'Asia/Dhaka',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE projects (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,slug VARCHAR(190) NOT NULL UNIQUE,title VARCHAR(190) NOT NULL,subtitle VARCHAR(255),short_description TEXT,overview TEXT,problem TEXT,solution TEXT,features JSON,challenges TEXT,lessons_learned TEXT,contribution TEXT,category VARCHAR(80),status VARCHAR(80),github_url VARCHAR(500),live_url VARCHAR(500),thumbnail_url VARCHAR(500),is_published BOOLEAN NOT NULL DEFAULT FALSE,display_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_projects_published_order(is_published,display_order));
CREATE TABLE project_images (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,project_id BIGINT UNSIGNED NOT NULL,url VARCHAR(500) NOT NULL,alt_text VARCHAR(255),display_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE skill_categories (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL UNIQUE,display_order INT DEFAULT 0);
CREATE TABLE skills (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,category_id BIGINT UNSIGNED NOT NULL,name VARCHAR(100) NOT NULL,icon VARCHAR(100),is_published BOOLEAN DEFAULT TRUE,display_order INT DEFAULT 0,UNIQUE(category_id,name),FOREIGN KEY(category_id) REFERENCES skill_categories(id) ON DELETE CASCADE);
CREATE TABLE project_skills (project_id BIGINT UNSIGNED NOT NULL,skill_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(project_id,skill_id),FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE,FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE);
CREATE TABLE education (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,institution VARCHAR(190) NOT NULL,degree VARCHAR(255) NOT NULL,status VARCHAR(120),credits_completed DECIMAL(6,2),cgpa DECIMAL(4,2),start_date DATE,end_date DATE,description TEXT,is_published BOOLEAN DEFAULT TRUE,display_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE experience (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,organization VARCHAR(190) NOT NULL,title VARCHAR(190) NOT NULL,previous_title VARCHAR(190),description TEXT,start_date DATE,end_date DATE,is_published BOOLEAN DEFAULT TRUE,display_order INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE messages (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,subject VARCHAR(255) NOT NULL,message TEXT NOT NULL,status ENUM('new','read','archived') DEFAULT 'new',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_messages_status_date(status,created_at));
CREATE TABLE meetings (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,type VARCHAR(120) NOT NULL,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL,message TEXT,start_time_utc DATETIME NOT NULL,end_time_utc DATETIME NOT NULL,timezone VARCHAR(80) NOT NULL,status ENUM('pending','confirmed','completed','cancelled','rejected') DEFAULT 'pending',admin_notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_meeting_slot(start_time_utc,end_time_utc),INDEX idx_meeting_status_start(status,start_time_utc));
CREATE TABLE availability (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,day_of_week TINYINT UNSIGNED,start_time TIME,end_time TIME,timezone VARCHAR(80) DEFAULT 'Asia/Dhaka',is_active BOOLEAN DEFAULT TRUE);
CREATE TABLE task_categories (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE tasks (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,category_id BIGINT UNSIGNED,title VARCHAR(255) NOT NULL,notes TEXT,priority ENUM('low','medium','high','urgent') DEFAULT 'medium',due_at DATETIME,status ENUM('todo','in_progress','completed') DEFAULT 'todo',recurrence_rule VARCHAR(255),completed_at DATETIME,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES task_categories(id) ON DELETE SET NULL,INDEX idx_tasks_status_due(status,due_at));
CREATE TABLE notifications (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,type VARCHAR(80) NOT NULL,title VARCHAR(190) NOT NULL,body TEXT,entity_type VARCHAR(80),entity_id BIGINT UNSIGNED,is_read BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_notifications_read_date(is_read,created_at));
CREATE TABLE ai_conversations (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(255) NOT NULL,context_enabled BOOLEAN DEFAULT FALSE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE ai_messages (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,conversation_id BIGINT UNSIGNED NOT NULL,role ENUM('user','assistant','system') NOT NULL,content MEDIUMTEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(conversation_id) REFERENCES ai_conversations(id) ON DELETE CASCADE,INDEX idx_ai_messages_conversation_date(conversation_id,created_at));
